use super::*;

/// Debts worst-rate first — the order avalanche pays them in, and the order to read them in.
pub fn by_cost(p: &Position) -> Vec<&AccountPosition> {
    let mut d: Vec<&AccountPosition> = p.accounts.iter().filter(|a| a.owed.is_some()).collect();
    d.sort_by(|a, b| b.apr.unwrap_or(-1.0).partial_cmp(&a.apr.unwrap_or(-1.0)).unwrap_or(std::cmp::Ordering::Equal));
    d
}
